//! Independent OAS 3.2 HTTP contract oracles, through the public compilation seam.
//! Normative sources and deliberately unsupported resolver semantics are recorded
//! in docs/SDK-OAS32-CONTRACT.md. Expected tokens, statuses and addresses below
//! are literals from the fixtures, not values generated by the implementation.

use std::collections::BTreeMap;
use std::sync::Arc;

use serde_json::{Value, json};
use suspect_ir::contract::{
    Contract, ContractReader, ContractSeverity, HttpMethod, OAuthFlowKind, OperationKind,
    ParameterLocation, ParameterStyle, ResponseStatus, SchemaDialect, SourceId,
};
use suspect_low::Pointer;
use suspect_ref::WorkspaceBuilder;
use suspect_source::Uri;

fn fixture(files: &[(&str, Value)]) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    for (name, value) in files {
        std::fs::write(
            dir.path().join(name),
            serde_json::to_vec_pretty(value).unwrap(),
        )
        .unwrap();
    }
    dir
}

fn load(dir: &tempfile::TempDir, entry: &str, reader: ContractReader) -> Contract {
    let workspace = Arc::new(WorkspaceBuilder::new().root(dir.path()).build().unwrap());
    Contract::from_workspace_with_reader(
        &workspace,
        &Uri::from_path(&dir.path().join(entry)).unwrap(),
        reader,
    )
    .unwrap()
}

fn id(uri: &Uri, pointer: &str) -> SourceId {
    SourceId::new(uri.clone(), Pointer::parse(pointer).unwrap())
}

fn located(contract: &Contract, source: &SourceId, code: &str) {
    let diagnostic = contract
        .diagnostics()
        .iter()
        .find(|d| &d.source == source && d.code == code)
        .unwrap_or_else(|| panic!("missing {code} at {source:?}: {:?}", contract.diagnostics()));
    assert_eq!(diagnostic.severity, ContractSeverity::Error);
    assert!(contract.source(&diagnostic.source).is_some());
    assert!(!diagnostic.at.is_empty(), "{diagnostic:?}");
}

fn clean(contract: &Contract) {
    assert!(!contract.has_errors(), "{:?}", contract.diagnostics());
}

fn both(dir: &tempfile::TempDir, check: impl Fn(&Contract)) {
    let left = load(dir, "api.json", ContractReader::Lossless);
    let right = load(dir, "api.json", ContractReader::Fast);
    check(&left);
    check(&right);
    parity(&left, &right);
}

fn parity(left: &Contract, right: &Contract) {
    assert_eq!(
        left.documents().collect::<Vec<_>>(),
        right.documents().collect::<Vec<_>>()
    );
    assert_eq!(left.schema_roots(), right.schema_roots());
    let schemas = |contract: &Contract| {
        contract
            .schemas()
            .map(|schema| {
                (
                    schema.id().clone(),
                    (
                        schema.raw().clone(),
                        schema.dialect().clone(),
                        schema.children().to_vec(),
                        schema.references().to_vec(),
                        schema.span(),
                    ),
                )
            })
            .collect::<BTreeMap<_, _>>()
    };
    assert_eq!(schemas(left), schemas(right));
    let diagnostics = |contract: &Contract| {
        contract
            .diagnostics()
            .iter()
            .map(|d| {
                (
                    d.source.clone(),
                    d.code,
                    d.severity,
                    d.message.clone(),
                    d.at.clone(),
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(diagnostics(left), diagnostics(right));
    let operations = |contract: &Contract| {
        contract
            .operations()
            .chain(contract.webhooks())
            .chain(contract.callbacks())
            .map(|op| {
                (
                    op.source().clone(),
                    op.path_item_source().clone(),
                    op.kind(),
                    op.method().as_str().to_owned(),
                    op.server_source().cloned(),
                    op.security_source().cloned(),
                    op.parameters()
                        .into_iter()
                        .map(|p| {
                            (
                                p.source().clone(),
                                p.resolved_source(),
                                p.name().map(str::to_owned),
                                p.location(),
                            )
                        })
                        .collect::<Vec<_>>(),
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(operations(left), operations(right));
}

fn api(path_item: Value) -> Value {
    json!({"openapi":"3.2.0","info":{"title":"OAS32 contract","version":"1"},"paths":{"/resource":path_item}})
}

fn querystring(name: &str) -> Value {
    json!({"name":name,"in":"querystring","content":{"application/json":{"schema":{"type":"object"}}}})
}

#[test]
fn query_and_additional_operations_preserve_case_sensitive_http_tokens() {
    let dir = fixture(&[(
        "api.json",
        api(json!({
            "get":{"responses":{"200":{}}},
            "query":{"requestBody":{"content":{"application/json":{"schema":{"type":"object"}}}},"responses":{"207":{}}},
            "additionalOperations":{
                "COPY":{"responses":{"204":{}}},
                "CONNECT":{"responses":{"200":{}}},
                "get":{"responses":{"201":{}}},
                "GeT":{"responses":{"202":{}}},
                "Query":{"responses":{"203":{}}},
                "x-purge":{"responses":{"205":{}}},
                "M-SEARCH":{"responses":{"206":{}}},
                "!#$%&'*+-.^_`|~":{"responses":{"208":{}}}
            }
        })),
    )]);
    both(&dir, |contract| {
        clean(contract);
        let expected = [
            (
                "!#$%&'*+-.^_`|~",
                "/paths/~1resource/additionalOperations/!#$%&'*+-.^_`|~0",
                208,
            ),
            (
                "CONNECT",
                "/paths/~1resource/additionalOperations/CONNECT",
                200,
            ),
            ("COPY", "/paths/~1resource/additionalOperations/COPY", 204),
            ("GET", "/paths/~1resource/get", 200),
            ("GeT", "/paths/~1resource/additionalOperations/GeT", 202),
            (
                "M-SEARCH",
                "/paths/~1resource/additionalOperations/M-SEARCH",
                206,
            ),
            ("QUERY", "/paths/~1resource/query", 207),
            ("Query", "/paths/~1resource/additionalOperations/Query", 203),
            ("get", "/paths/~1resource/additionalOperations/get", 201),
            (
                "x-purge",
                "/paths/~1resource/additionalOperations/x-purge",
                205,
            ),
        ];
        let operations = contract.operations().collect::<Vec<_>>();
        assert_eq!(operations.len(), expected.len());
        for (operation, (token, pointer, status)) in operations.iter().zip(expected) {
            assert_eq!(operation.method().as_str(), token);
            assert_eq!(operation.method().to_string(), token);
            let copied = operation.method();
            assert_eq!(copied, operation.method()); // borrowed method remains Copy
            assert_eq!(operation.source(), &id(contract.entry(), pointer));
            assert_eq!(operation.path_template(), Some("/resource"));
            assert_eq!(operation.kind(), OperationKind::Client);
            assert_eq!(
                operation.responses()[0].status(),
                Some(ResponseStatus::Exact(status))
            );
            assert!(contract.source_span(operation.source()).is_some());
        }
        assert_eq!(suspect_ir::Method::ALL.len(), 8);
        assert!(
            operations
                .iter()
                .find(|op| op.method().as_str() == "GET")
                .unwrap()
                .method()
                == suspect_ir::Method::Get
        );
        assert!(
            operations
                .iter()
                .find(|op| op.method().as_str() == "get")
                .unwrap()
                .method()
                != suspect_ir::Method::Get
        );
    });
    for invalid in [
        "", "GET ", "A B", "A/B", "A:B", "A(B)", "[GET]", "GÉT", "A\tB", "A\r\nB", "A\0B",
    ] {
        assert!(HttpMethod::parse(invalid).is_none(), "{invalid:?}");
    }
}

#[test]
fn invalid_methods_and_duplicate_fixed_methods_are_not_indexed_as_get() {
    let dir = fixture(&[(
        "api.json",
        api(json!({
            "get":{"responses":{"200":{}}},
            "additionalOperations":{
                "GET":{},"PUT":{},"POST":{},"DELETE":{},"OPTIONS":{},"HEAD":{},"PATCH":{},"TRACE":{},"QUERY":{},
                "":{},"A B":{},"GÉT":{},"A/B":{},"A:B":{},"A\nB":{},
                "COPY":false,"ok":{}
            }
        })),
    )]);
    both(&dir, |contract| {
        assert_eq!(
            contract
                .operations()
                .map(|op| op.method().as_str())
                .collect::<Vec<_>>(),
            ["GET", "ok"]
        );
        let root = id(contract.entry(), "/paths/~1resource/additionalOperations");
        for token in [
            "GET", "PUT", "POST", "DELETE", "OPTIONS", "HEAD", "PATCH", "TRACE", "QUERY",
        ] {
            located(contract, &root.child(token), "DUPLICATE_HTTP_METHOD");
        }
        for token in ["", "A B", "GÉT", "A/B", "A:B", "A\nB"] {
            located(contract, &root.child(token), "INVALID_HTTP_METHOD");
        }
        located(contract, &root.child("COPY"), "INVALID_HTTP_SHAPE");
    });
    for malformed in [Value::Null, json!(17), json!([]), json!("COPY")] {
        let dir = fixture(&[(
            "api.json",
            api(json!({"query":false,"additionalOperations":malformed})),
        )]);
        both(&dir, |contract| {
            assert_eq!(contract.operations().count(), 0);
            located(
                contract,
                &id(contract.entry(), "/paths/~1resource/query"),
                "INVALID_HTTP_SHAPE",
            );
            located(
                contract,
                &id(contract.entry(), "/paths/~1resource/additionalOperations"),
                "INVALID_HTTP_SHAPE",
            );
        });
    }
}

#[test]
fn querystring_name_identifies_overrides_but_never_implies_style_serialization() {
    let dir = fixture(&[(
        "api.json",
        json!({
            "openapi":"3.2.0","info":{"title":"Query string","version":"1"},
            "components":{"parameters":{"Whole":{"name":"criteria","in":"querystring","content":{"application/x-www-form-urlencoded":{"schema":{"type":"object","properties":{"term":{"type":"string"}}},"encoding":{"term":{"style":"form"}}}}}}},
            "paths":{"/resource":{"parameters":[{"$ref":"#/components/parameters/Whole"}],
                "query":{"parameters":[{"name":"criteria","in":"querystring","required":true,"content":{"application/json":{"schema":{"type":"object","required":["term"],"properties":{"term":{"type":"string"}}}}}}],"responses":{"200":{}}},
                "additionalOperations":{"SEARCH":{"responses":{"200":{}}}}
            }}
        }),
    )]);
    both(&dir, |contract| {
        clean(contract);
        let query = contract
            .operations()
            .find(|op| op.method().as_str() == "QUERY")
            .unwrap();
        let parameters = query.parameters();
        assert_eq!(parameters.len(), 1);
        let whole = &parameters[0];
        assert_eq!(whole.name(), Some("criteria"));
        assert_eq!(whole.location(), Some(ParameterLocation::Querystring));
        assert_eq!(whole.required(), Some(true));
        assert_eq!(
            whole.source().pointer(),
            "/paths/~1resource/query/parameters/0"
        );
        assert!(whole.schema().is_none());
        assert!(whole.effective_style().is_none());
        assert!(whole.effective_explode().is_none());
        assert_eq!(whole.content()[0].name(), "application/json");
        assert_eq!(
            whole.content()[0].schema().unwrap().id().pointer(),
            "/paths/~1resource/query/parameters/0/content/application~1json/schema"
        );
        assert_eq!(
            query.parameter_collections(),
            [
                id(contract.entry(), "/paths/~1resource/parameters"),
                id(contract.entry(), "/paths/~1resource/query/parameters"),
            ]
        );
        let inherited = contract
            .operations()
            .find(|op| op.method().as_str() == "SEARCH")
            .unwrap()
            .parameters()
            .remove(0);
        assert_eq!(inherited.name(), Some("criteria"));
        assert_eq!(
            inherited.source().pointer(),
            "/paths/~1resource/parameters/0"
        );
        assert_eq!(
            inherited.resolved_source().unwrap().pointer(),
            "/components/parameters/Whole"
        );
        assert_eq!(inherited.content()[0].encoding()[0].name(), "term");
    });
}

#[test]
fn querystring_uniqueness_and_query_exclusion_include_path_item_inheritance() {
    let query = json!({"name":"q","in":"query","schema":{"type":"string"}});
    for (shared, declared, expected, pointer) in [
        (
            vec![],
            vec![querystring("a"), querystring("b")],
            "DUPLICATE_QUERYSTRING_PARAMETER",
            "/paths/~1resource/query/parameters/1",
        ),
        (
            vec![querystring("a")],
            vec![querystring("b")],
            "DUPLICATE_QUERYSTRING_PARAMETER",
            "/paths/~1resource/query/parameters/0",
        ),
        (
            vec![query.clone()],
            vec![querystring("a")],
            "INVALID_QUERYSTRING_COMBINATION",
            "/paths/~1resource/query/parameters/0",
        ),
        (
            vec![querystring("a")],
            vec![query.clone()],
            "INVALID_QUERYSTRING_COMBINATION",
            "/paths/~1resource/parameters/0",
        ),
        (
            vec![],
            vec![querystring("a"), query],
            "INVALID_QUERYSTRING_COMBINATION",
            "/paths/~1resource/query/parameters/0",
        ),
        (
            vec![],
            vec![querystring("a"), querystring("a")],
            "DUPLICATE_PARAMETER",
            "/paths/~1resource/query/parameters/1",
        ),
    ] {
        let dir = fixture(&[(
            "api.json",
            api(json!({"parameters":shared,"query":{"parameters":declared}})),
        )]);
        both(&dir, |contract| {
            located(contract, &id(contract.entry(), pointer), expected)
        });
    }
    // Required string names may be empty. Serialization still uses the whole
    // query string; the empty name is a valid override identity.
    let dir = fixture(&[(
        "api.json",
        api(json!({"parameters":[querystring("")],"query":{"parameters":[querystring("")]}})),
    )]);
    both(&dir, |contract| {
        clean(contract);
        assert_eq!(contract.operations().next().unwrap().parameters().len(), 1);
    });
}

#[test]
fn querystring_requires_name_and_exactly_one_content_entry_and_forbids_schema_fields() {
    for (field, value, code) in [
        (
            "schema",
            json!({"type":"object"}),
            "INVALID_QUERYSTRING_PARAMETER",
        ),
        ("style", json!("form"), "INVALID_QUERYSTRING_PARAMETER"),
        ("explode", json!(false), "INVALID_QUERYSTRING_PARAMETER"),
        (
            "allowReserved",
            json!(false),
            "INVALID_QUERYSTRING_PARAMETER",
        ),
        ("allowEmptyValue", json!(false), "INVALID_PARAMETER_FIELD"),
        ("content", json!({}), "INVALID_PARAMETER_CONTENT"),
        (
            "content",
            json!({"application/json":{},"text/plain":{}}),
            "INVALID_PARAMETER_CONTENT",
        ),
        ("content", Value::Null, "INVALID_HTTP_SHAPE"),
        ("content", json!([]), "INVALID_HTTP_SHAPE"),
        ("name", json!(7), "INVALID_HTTP_SHAPE"),
    ] {
        let mut parameter = querystring("whole");
        parameter[field] = value;
        let dir = fixture(&[("api.json", api(json!({"query":{"parameters":[parameter]}})))]);
        both(&dir, |contract| {
            located(
                contract,
                &id(contract.entry(), "/paths/~1resource/query/parameters/0").child(field),
                code,
            );
            let parameter = contract.operations().next().unwrap().parameters().remove(0);
            assert!(parameter.effective_style().is_none());
            assert!(parameter.effective_explode().is_none());
        });
    }
    for removed in ["name", "content"] {
        let mut parameter = querystring("whole");
        parameter.as_object_mut().unwrap().remove(removed);
        let dir = fixture(&[("api.json", api(json!({"query":{"parameters":[parameter]}})))]);
        both(&dir, |contract| {
            located(
                contract,
                &id(contract.entry(), "/paths/~1resource/query/parameters/0"),
                "INVALID_HTTP_SHAPE",
            )
        });
    }
}

#[test]
fn split_media_references_keep_both_schema_roots_mounts_statuses_and_recursive_targets() {
    let dir = fixture(&[
        (
            "api.json",
            json!({
                "openapi":"3.2.0","info":{"title":"Split stream","version":"1"},
                "servers":[{"name":"root","url":"https://api.example.test"}],
                "security":[{"key":[]}],
                "components":{"securitySchemes":{"key":{"type":"apiKey","in":"header","name":"X-Key"}},"mediaTypes":{"Stream":{"$ref":"media.json#/Forward"}}},
                "paths":{"/events":{"$ref":"routes.json#/Route"}}
            }),
        ),
        (
            "routes.json",
            json!({"Route":{
                "servers":[{"name":"stream","url":"./stream"}],
                "parameters":[{"$ref":"http.json#/Whole"}],
                "query":{"requestBody":{"$ref":"http.json#/Body"},"responses":{"206":{"$ref":"http.json#/Reply"},"2XX":{},"default":{}}},
                "additionalOperations":{"Subscribe":{"servers":[],"security":[],"responses":{"202":{}}}}
            }}),
        ),
        (
            "http.json",
            json!({
                "Whole":{"name":"whole","in":"querystring","content":{"application/json-seq":{"$ref":"media.json#/Forward"}}},
                "Body":{"required":true,"content":{"application/json-seq":{"$ref":"media.json#/Forward"}}},
                "Reply":{"summary":"A sequence","headers":{"X-Sequence":{"content":{"application/json-seq":{"$ref":"media.json#/Forward"}}}},"content":{
                    "application/json-seq":{"$ref":"media.json#/Forward"},
                    "text/event-stream":{"$ref":"media.json#/Forward"}
                }}
            }),
        ),
        (
            "media.json",
            json!({
                "Forward":{"$ref":"#/Sequence","itemSchema":{"$ref":"must-not-load-ignored.json"}},
                "Sequence":{
                    "schema":{"type":"array","items":{"$ref":"schema.json#/$defs/Event"}},
                    "itemSchema":{"$ref":"schema.json#/$defs/Event"},
                    "examples":{"data":{"dataValue":[{"$ref":"must-not-load-instance.json","schema":{"$anchor":"Event"},"itemSchema":{"type":"null"}}],"serializedValue":"{\"data\":\"hello\"}\n"}}
                }
            }),
        ),
        (
            "schema.json",
            json!({"$defs":{"Event":{"$anchor":"Event","type":"object","properties":{"data":{"type":"string"},"next":{"$ref":"#Event"}}}}}),
        ),
    ]);
    both(&dir, |contract| {
        clean(contract);
        assert_eq!(contract.documents().count(), 5);
        let routes = Uri::from_path(&dir.path().join("routes.json")).unwrap();
        let http = Uri::from_path(&dir.path().join("http.json")).unwrap();
        let media = Uri::from_path(&dir.path().join("media.json")).unwrap();
        let schemas = Uri::from_path(&dir.path().join("schema.json")).unwrap();
        let operation = contract
            .operations()
            .find(|op| op.method().as_str() == "QUERY")
            .unwrap();
        assert_eq!(operation.source(), &id(&routes, "/Route/query"));
        assert_eq!(
            operation.path_item_source(),
            &id(contract.entry(), "/paths/~1events")
        );
        assert_eq!(operation.path_template(), Some("/events"));
        assert_eq!(
            operation.server_source(),
            Some(&id(&routes, "/Route/servers"))
        );
        assert_eq!(operation.effective_servers()[0].name(), Some("stream"));
        assert_eq!(operation.effective_servers()[0].url(), Some("./stream"));
        assert_eq!(
            operation.security_source(),
            Some(&id(contract.entry(), "/security"))
        );
        assert_eq!(
            operation.effective_security()[0].requirements()[0]
                .scheme()
                .unwrap()
                .parameter_name(),
            Some("X-Key")
        );
        let cleared = contract
            .operations()
            .find(|op| op.method().as_str() == "Subscribe")
            .unwrap();
        assert_eq!(
            cleared.server_source(),
            Some(&id(
                &routes,
                "/Route/additionalOperations/Subscribe/servers"
            ))
        );
        assert!(cleared.effective_servers()[0].is_default());
        assert!(cleared.effective_security().is_empty());
        let body = operation.request_body().unwrap();
        assert_eq!(body.source(), &id(&routes, "/Route/query/requestBody"));
        assert_eq!(body.resolved_source(), Some(id(&http, "/Body")));
        let content = body.content().remove(0);
        assert_eq!(
            content.source(),
            &id(&http, "/Body/content/application~1json-seq")
        );
        assert_eq!(content.resolved_source(), Some(id(&media, "/Sequence")));
        assert_eq!(
            contract.reference_target(content.source()),
            Some(&id(&media, "/Forward"))
        );
        assert_eq!(
            contract.reference_target(&id(&media, "/Forward")),
            Some(&id(&media, "/Sequence"))
        );
        assert!(
            contract
                .reference_target(&content.source().child("$ref"))
                .is_none()
        );
        assert_eq!(content.name(), "application/json-seq");
        assert_eq!(
            content.schema().unwrap().id(),
            &id(&media, "/Sequence/schema")
        );
        assert_eq!(
            content.item_schema().unwrap().id(),
            &id(&media, "/Sequence/itemSchema")
        );
        assert_eq!(
            content.item_schema().unwrap().references()[0].target,
            Some(id(&schemas, "/$defs/Event"))
        );
        let closure = contract.reachable_from(&content.schema_roots());
        let mut expected = vec![
            id(&media, "/Sequence/schema"),
            id(&media, "/Sequence/schema/items"),
            id(&media, "/Sequence/itemSchema"),
            id(&schemas, "/$defs/Event"),
            id(&schemas, "/$defs/Event/properties/data"),
            id(&schemas, "/$defs/Event/properties/next"),
        ];
        expected.sort();
        assert_eq!(closure, expected);
        let parameter = operation.parameters().remove(0);
        assert_eq!(parameter.location(), Some(ParameterLocation::Querystring));
        assert_eq!(
            parameter.content()[0].schema_roots(),
            content.schema_roots()
        );
        let replies = operation.responses();
        assert_eq!(
            replies.iter().map(|r| r.status()).collect::<Vec<_>>(),
            [
                Some(ResponseStatus::Exact(206)),
                Some(ResponseStatus::Range(2)),
                Some(ResponseStatus::Default)
            ]
        );
        assert_eq!(
            replies[0].source(),
            &id(&routes, "/Route/query/responses/206")
        );
        assert_eq!(replies[0].summary(), Some("A sequence"));
        assert_eq!(
            replies[0]
                .content()
                .iter()
                .map(|m| m.name())
                .collect::<Vec<_>>(),
            ["application/json-seq", "text/event-stream"]
        );
        assert_eq!(
            replies[0].headers()[0].content()[0]
                .item_schema()
                .unwrap()
                .id(),
            content.item_schema().unwrap().id()
        );
        assert_eq!(contract.media_types()[0].name(), "Stream");
        assert_eq!(
            contract.media_types()[0].resolved_source(),
            Some(id(&media, "/Sequence"))
        );
        assert!(
            contract
                .schema(&id(&media, "/Forward/itemSchema"))
                .is_none()
        );
        assert!(
            !contract
                .schemas()
                .any(|s| s.id().pointer().contains("/dataValue"))
        );
        let example = content.examples().remove(0);
        assert!(example.value().is_none());
        assert_eq!(
            example.data_value().unwrap()[0]["$ref"],
            "must-not-load-instance.json"
        );
        assert_eq!(
            example.data_value_source(),
            Some(id(&media, "/Sequence/examples/data/dataValue"))
        );
        assert_eq!(example.serialized_value(), Some("{\"data\":\"hello\"}\n"));
        assert_eq!(
            example.serialized_value_source(),
            Some(id(&media, "/Sequence/examples/data/serializedValue"))
        );
    });
}

#[test]
fn item_schemas_and_positional_nested_encoding_header_schemas_are_real_graph_positions() {
    let dir = fixture(&[(
        "api.json",
        api(json!({"query":{
            "parameters":[{"name":"chunks","in":"header","content":{"application/json-seq":{"itemSchema":false}}}],
            "requestBody":{"content":{"multipart/mixed":{
                "itemSchema":{"type":"string"},
                "prefixEncoding":[
                    {"headers":{"X-Chunk":{"schema":{"type":"integer"}}}},
                    {"encoding":{"part":{"headers":{"X-Part":{"content":{"application/json-seq":{"itemSchema":{"type":"number"}}}}}}}}
                ],
                "itemEncoding":{"prefixEncoding":[{"headers":{"X-Nested":{"schema":true}}}],"itemEncoding":{"headers":{"X-Tail":{"schema":{"type":"boolean"}}}}},
                "examples":{"data":{"dataValue":{"schema":{"$ref":"never-load.json"},"itemSchema":{"$ref":"never-load.json"},"prefixEncoding":[{"headers":{"X-Fake":{"schema":null}}}]}}}
            }}},
            "responses":{"200":{"content":{"application/x-ndjson":{"schema":{"type":"array"},"itemSchema":{"type":"null"}}}}}
        }})),
    )]);
    both(&dir, |contract| {
        clean(contract);
        let expected = [
            "/paths/~1resource/query/parameters/0/content/application~1json-seq/itemSchema",
            "/paths/~1resource/query/requestBody/content/multipart~1mixed/itemSchema",
            "/paths/~1resource/query/requestBody/content/multipart~1mixed/prefixEncoding/0/headers/X-Chunk/schema",
            "/paths/~1resource/query/requestBody/content/multipart~1mixed/prefixEncoding/1/encoding/part/headers/X-Part/content/application~1json-seq/itemSchema",
            "/paths/~1resource/query/requestBody/content/multipart~1mixed/itemEncoding/prefixEncoding/0/headers/X-Nested/schema",
            "/paths/~1resource/query/requestBody/content/multipart~1mixed/itemEncoding/itemEncoding/headers/X-Tail/schema",
            "/paths/~1resource/query/responses/200/content/application~1x-ndjson/schema",
            "/paths/~1resource/query/responses/200/content/application~1x-ndjson/itemSchema",
        ];
        assert_eq!(contract.schema_roots().len(), expected.len());
        for pointer in expected {
            let source = id(contract.entry(), pointer);
            assert!(
                contract.schema_roots().contains(&source),
                "missing {pointer}"
            );
            assert!(contract.schema(&source).is_some());
            assert!(!contract.source_span(&source).unwrap().is_empty());
        }
        assert_eq!(contract.schemas().count(), expected.len());
        let op = contract.operations().next().unwrap();
        let media = op.request_body().unwrap().content().remove(0);
        assert!(media.schema().is_none());
        assert_eq!(media.prefix_encoding().len(), 2);
        assert_eq!(
            media.prefix_encoding()[0].headers()[0]
                .schema()
                .unwrap()
                .raw()["type"],
            "integer"
        );
        assert_eq!(media.prefix_encoding()[1].encoding()[0].name(), "part");
        assert_eq!(
            media.item_encoding().unwrap().prefix_encoding()[0].headers()[0]
                .schema()
                .unwrap()
                .raw(),
            &json!(true)
        );
        assert_eq!(
            media
                .item_encoding()
                .unwrap()
                .item_encoding()
                .unwrap()
                .headers()[0]
                .name(),
            "X-Tail"
        );
        assert_eq!(
            op.parameters()[0].content()[0].item_schema().unwrap().raw(),
            &json!(false)
        );
    });
}

#[test]
