#[test]
fn callbacks_and_webhooks_keep_direction_and_exact_additional_method_identity() {
    let dir = fixture(&[(
        "api.json",
        json!({
            "openapi":"3.2.0","info":{"title":"Directions","version":"1"},
            "paths":{"/subscribe":{"query":{"operationId":"subscribe","callbacks":{"x-notification":{"{$request.querystring}":{
                "query":{"operationId":"callbackQuery","requestBody":{"content":{"application/json-seq":{"itemSchema":{"type":"string"}}}}},
                "additionalOperations":{"Deliver":{"operationId":"deliver"}}
            }}}}}},
            "webhooks":{"x-event":{"query":{"operationId":"webhookQuery"},"additionalOperations":{"notify":{"operationId":"notify"}}}}
        }),
    )]);
    both(&dir, |contract| {
        clean(contract);
        assert_eq!(
            contract
                .operations()
                .map(|op| op.method().as_str())
                .collect::<Vec<_>>(),
            ["QUERY"]
        );
        assert_eq!(
            contract
                .webhooks()
                .map(|op| op.method().as_str())
                .collect::<Vec<_>>(),
            ["QUERY", "notify"]
        );
        assert_eq!(
            contract
                .callbacks()
                .map(|op| op.method().as_str())
                .collect::<Vec<_>>(),
            ["Deliver", "QUERY"]
        );
        let parent = id(contract.entry(), "/paths/~1subscribe/query");
        for webhook in contract.webhooks() {
            assert_eq!(webhook.kind(), OperationKind::Webhook);
            assert_eq!(webhook.webhook_name(), Some("x-event"));
            assert!(webhook.path_template().is_none());
            assert!(webhook.callback_parent().is_none());
        }
        for callback in contract.callbacks() {
            assert_eq!(callback.kind(), OperationKind::Callback);
            assert_eq!(callback.callback_parent(), Some(&parent));
            assert_eq!(callback.callback_name(), Some("x-notification"));
            assert_eq!(
                callback.callback_expression(),
                Some("{$request.querystring}")
            );
            assert!(callback.path_template().is_none());
        }
        let callback = contract
            .callbacks()
            .find(|op| op.method().as_str() == "QUERY")
            .unwrap();
        assert_eq!(
            callback.request_body().unwrap().content()[0]
                .item_schema()
                .unwrap()
                .raw()["type"],
            "string"
        );
    });
}

#[test]
fn response_status_identity_and_optional_32_descriptions_have_literal_oracles() {
    let dir = fixture(&[(
        "api.json",
        api(json!({"query":{"responses":{
            "100":{},"199":{},"200":{},"299":{},"599":{},"1XX":{},"2XX":{},"3XX":{},"4XX":{},"5XX":{},"default":{},
            "99":{},"600":{},"0200":{},"2xx":{},"20X":{}," 200":{},"2XX ":{},"x-extra":{"schema":"instance metadata"}
        }}})),
    )]);
    both(&dir, |contract| {
        let operation = contract.operations().next().unwrap();
        let responses = operation.responses();
        let expected = [
            ("100", ResponseStatus::Exact(100)),
            ("199", ResponseStatus::Exact(199)),
            ("200", ResponseStatus::Exact(200)),
            ("299", ResponseStatus::Exact(299)),
            ("599", ResponseStatus::Exact(599)),
            ("1XX", ResponseStatus::Range(1)),
            ("2XX", ResponseStatus::Range(2)),
            ("3XX", ResponseStatus::Range(3)),
            ("4XX", ResponseStatus::Range(4)),
            ("5XX", ResponseStatus::Range(5)),
            ("default", ResponseStatus::Default),
        ];
        for (key, status) in expected {
            let response = responses
                .iter()
                .find(|response| response.status_key() == key)
                .unwrap();
            assert_eq!(response.status(), Some(status));
            assert_eq!(
                response.source(),
                &id(contract.entry(), "/paths/~1resource/query/responses").child(key)
            );
        }
        for key in ["99", "600", "0200", "2xx", "20X", " 200", "2XX "] {
            assert_eq!(
                responses
                    .iter()
                    .find(|r| r.status_key() == key)
                    .unwrap()
                    .status(),
                None
            );
            located(
                contract,
                &id(contract.entry(), "/paths/~1resource/query/responses").child(key),
                "INVALID_RESPONSE_STATUS",
            );
        }
        assert_eq!(responses.len(), 18);
        assert_eq!(contract.diagnostics().len(), 7);
    });
    for (version, missing_description_is_error) in
        [("3.0.4", true), ("3.1.2", true), ("3.2.0", false)]
    {
        let mut value = api(json!({"get":{"responses":{"200":{}}}}));
        value["openapi"] = json!(version);
        let dir = fixture(&[("api.json", value)]);
        both(&dir, |contract| {
            assert_eq!(contract.has_errors(), missing_description_is_error);
            if missing_description_is_error {
                located(
                    contract,
                    &id(contract.entry(), "/paths/~1resource/get/responses/200"),
                    "INVALID_HTTP_SHAPE",
                );
            }
        });
    }
}

#[test]
fn http_metadata_fields_are_32_only_and_are_typed_without_invented_defaults() {
    for version in ["3.0.4", "3.1.2", "3.2.0"] {
        let dir = fixture(&[
            (
                "api.json",
                json!({
                    "openapi":version,"info":{"title":"Version matrix","version":"1"},
                    "servers":[{"url":"https://api.example.test","name":"production"}],
                    "security":[{"oauth":[]}],
                    "components":{
                        "mediaTypes":{"Sequence":{"itemSchema":{"type":"string"}}},
                        "securitySchemes":{"oauth":{"type":"oauth2","deprecated":false,"oauth2MetadataUrl":"https://auth.example.test/.well-known/oauth-authorization-server","flows":{
                            "deviceAuthorization":{"deviceAuthorizationUrl":"https://auth.example.test/device","tokenUrl":"https://auth.example.test/token","scopes":{}}
                        }}}
                    },
                    "paths":{"/resource":{
                        "query":{},"additionalOperations":{"copy":{}},
                        "get":{"parameters":[
                            {"name":"session","in":"cookie","style":"cookie","schema":{"type":"string"}},
                            querystring("whole")
                        ],"responses":{"200":{"description":"OK","summary":"Result","content":{
                            "multipart/mixed":{"schema":{"type":"array"},"itemSchema":{"type":"string"},"prefixEncoding":[],"itemEncoding":{},"examples":{"data":{"dataValue":["x"],"serializedValue":"x"}}},
                            "application/json-seq":{"$ref":"media.json#/Sequence"}
                        }}}}
                    }}
                }),
            ),
            ("media.json", json!({"Sequence":{"itemSchema":true}})),
        ]);
        both(&dir, |contract| {
            let modern = version == "3.2.0";
            assert_eq!(
                contract.has_errors(),
                !modern,
                "{:?}",
                contract.diagnostics()
            );
            assert_eq!(contract.operations().count(), if modern { 3 } else { 1 });
            assert_eq!(contract.documents().count(), if modern { 2 } else { 1 });
            assert_eq!(contract.media_types().len(), usize::from(modern));
            let operation = contract
                .operations()
                .find(|op| op.method().as_str() == "GET")
                .unwrap();
            assert_eq!(
                operation.effective_servers()[0].name(),
                modern.then_some("production")
            );
            let cookie = operation.parameters().remove(0);
            assert_eq!(cookie.style(), modern.then_some(ParameterStyle::Cookie));
            assert_eq!(cookie.effective_explode(), modern.then_some(true));
            assert_eq!(
                operation.parameters()[1].location(),
                modern.then_some(ParameterLocation::Querystring)
            );
            let response = operation.responses().remove(0);
            assert_eq!(response.summary(), modern.then_some("Result"));
            let multipart = response
                .content()
                .into_iter()
                .find(|m| m.name() == "multipart/mixed")
                .unwrap();
            assert_eq!(multipart.item_schema().is_some(), modern);
            assert_eq!(multipart.item_encoding().is_some(), modern);
            assert_eq!(
                multipart.examples()[0].data_value(),
                modern.then_some(&json!(["x"]))
            );
            assert_eq!(
                multipart.examples()[0].serialized_value(),
                modern.then_some("x")
            );
            let oauth = contract.security_schemes().remove(0);
            assert_eq!(oauth.deprecated(), modern.then_some(false));
            assert_eq!(
                oauth.oauth2_metadata_url(),
                modern
                    .then_some("https://auth.example.test/.well-known/oauth-authorization-server")
            );
            let flow = oauth.flows().remove(0);
            assert_eq!(
                flow.kind(),
                modern.then_some(OAuthFlowKind::DeviceAuthorization)
            );
            assert_eq!(
                flow.device_authorization_url(),
                modern.then_some("https://auth.example.test/device")
            );
            if !modern {
                for pointer in [
                    "/servers/0/name",
                    "/components/mediaTypes",
                    "/paths/~1resource/query",
                    "/paths/~1resource/additionalOperations",
                    "/paths/~1resource/get/responses/200/summary",
                    "/paths/~1resource/get/responses/200/content/application~1json-seq/$ref",
                    "/paths/~1resource/get/responses/200/content/multipart~1mixed/itemSchema",
                    "/paths/~1resource/get/responses/200/content/multipart~1mixed/prefixEncoding",
                    "/paths/~1resource/get/responses/200/content/multipart~1mixed/itemEncoding",
                    "/paths/~1resource/get/responses/200/content/multipart~1mixed/examples/data/dataValue",
                    "/paths/~1resource/get/responses/200/content/multipart~1mixed/examples/data/serializedValue",
                    "/components/securitySchemes/oauth/deprecated",
                    "/components/securitySchemes/oauth/oauth2MetadataUrl",
                ] {
                    located(
                        contract,
                        &id(contract.entry(), pointer),
                        "UNSUPPORTED_HTTP_FIELD",
                    );
                }
                located(
                    contract,
                    &id(contract.entry(), "/paths/~1resource/get/parameters/0/style"),
                    "INVALID_PARAMETER_STYLE",
                );
                located(
                    contract,
                    &id(contract.entry(), "/paths/~1resource/get/parameters/1/in"),
                    "UNSUPPORTED_PARAMETER_LOCATION",
                );
                located(
                    contract,
                    &id(
                        contract.entry(),
                        "/components/securitySchemes/oauth/flows/deviceAuthorization",
                    ),
                    "UNSUPPORTED_OAUTH_FLOW",
                );
                assert!(
                    !contract
                        .schemas()
                        .any(|s| s.id().pointer().ends_with("/itemSchema"))
                );
            }
        });
    }
}

#[test]
fn declaring_document_versions_survive_ref_mounts_and_propagate_to_standalone_media() {
    let dir = fixture(&[
        (
            "api.json",
            json!({"openapi":"3.1.2","info":{"title":"Entry","version":"1"},"paths":{"/remote":{"$ref":"remote.json#/paths/~1route"}}}),
        ),
        (
            "remote.json",
            json!({"openapi":"3.2.0","info":{"title":"Remote","version":"1"},"paths":{"/route":{
                "query":{"requestBody":{"content":{"application/json-seq":{"$ref":"media.json#/Sequence"}}},"parameters":[querystring("whole")]},
                "additionalOperations":{"M-SEARCH":{}}
            }}}),
        ),
        (
            "media.json",
            json!({"Sequence":{"itemSchema":{"type":"string"}}}),
        ),
    ]);
    both(&dir, |contract| {
        clean(contract);
        assert_eq!(contract.openapi_version(), "3.1.2");
        assert_eq!(
            contract
                .operations()
                .map(|op| op.method().as_str())
                .collect::<Vec<_>>(),
            ["M-SEARCH", "QUERY"]
        );
        let query = contract
            .operations()
            .find(|op| op.method().as_str() == "QUERY")
            .unwrap();
        assert_eq!(contract.openapi_version_at(query.source()), "3.2.0");
        assert_eq!(query.path_item_source().document(), contract.entry());
        assert_eq!(
            query.parameters()[0].location(),
            Some(ParameterLocation::Querystring)
        );
        let media = query.request_body().unwrap().content().remove(0);
        let schema = media.item_schema().unwrap();
        assert_eq!(
            schema.id(),
            &id(
                &Uri::from_path(&dir.path().join("media.json")).unwrap(),
                "/Sequence/itemSchema"
            )
        );
        assert_eq!(contract.openapi_version_at(schema.id()), "3.2.0");
        assert_eq!(
            schema.dialect(),
            &SchemaDialect::Uri("https://spec.openapis.org/oas/3.1/dialect/base".to_owned())
        );
    });

    let dir = fixture(&[
        (
            "api.json",
            json!({"openapi":"3.2.0","info":{"title":"Entry","version":"1"},"paths":{"/remote":{"$ref":"remote.json#/paths/~1route"}}}),
        ),
        (
            "remote.json",
            json!({"openapi":"3.1.2","info":{"title":"Remote","version":"1"},"paths":{"/route":{
                "query":{},"additionalOperations":{"COPY":{}},
                "get":{"responses":{"200":{"description":"OK","content":{"application/json-seq":{"itemSchema":{"$ref":"never-load.json"}}}}}}
            }}}),
        ),
    ]);
    both(&dir, |contract| {
        assert_eq!(
            contract
                .operations()
                .map(|op| op.method().as_str())
                .collect::<Vec<_>>(),
            ["GET"]
        );
        let remote = Uri::from_path(&dir.path().join("remote.json")).unwrap();
        for pointer in [
            "/paths/~1route/query",
            "/paths/~1route/additionalOperations",
            "/paths/~1route/get/responses/200/content/application~1json-seq/itemSchema",
        ] {
            located(contract, &id(&remote, pointer), "UNSUPPORTED_HTTP_FIELD");
        }
        assert_eq!(contract.documents().count(), 2);
        assert_eq!(contract.schemas().count(), 0);
    });
}

#[test]
fn reusing_one_standalone_fragment_with_conflicting_versions_is_explicit() {
    let dir = fixture(&[
        (
            "api.json",
            json!({"openapi":"3.2.0","info":{"title":"Entry","version":"1"},"paths":{"/old":{"$ref":"old.json#/paths/~1route"},"/new":{"$ref":"new.json#/paths/~1route"}}}),
        ),
        (
            "old.json",
            json!({"openapi":"3.1.2","info":{"title":"Old","version":"1"},"paths":{"/route":{"get":{"responses":{"200":{"description":"OK","content":{"application/json":{"$ref":"shared.json#/Media"}}}}}}}}),
        ),
        (
            "new.json",
            json!({"openapi":"3.2.0","info":{"title":"New","version":"1"},"paths":{"/route":{"get":{"responses":{"200":{"content":{"application/json":{"$ref":"shared.json#/Media"}}}}}}}}),
        ),
        ("shared.json", json!({"Media":{"schema":{"type":"string"}}})),
    ]);
    // A Media Type reference is itself a 3.2-only declaration in old.json;
    // the 3.1 source must not acquire 3.2 reference semantics through another use.
    both(&dir, |contract| {
        located(
            contract,
            &id(
                &Uri::from_path(&dir.path().join("old.json")).unwrap(),
                "/paths/~1route/get/responses/200/content/application~1json/$ref",
            ),
            "UNSUPPORTED_HTTP_FIELD",
        );
        let old = contract
            .operations()
            .find(|op| op.path_template() == Some("/old"))
            .unwrap();
        assert!(old.responses()[0].content()[0].schema().is_none());
    });

    let dir = fixture(&[
        (
            "api.json",
            json!({"openapi":"3.2.0","info":{"title":"Entry","version":"1"},"paths":{"/old":{"$ref":"old.json#/paths/~1route"},"/new":{"$ref":"new.json#/paths/~1route"}}}),
        ),
        (
            "old.json",
            json!({"openapi":"3.1.2","info":{"title":"Old","version":"1"},"paths":{"/route":{"get":{"requestBody":{"$ref":"shared.json#/Body"}}}}}),
        ),
        (
            "new.json",
            json!({"openapi":"3.2.0","info":{"title":"New","version":"1"},"paths":{"/route":{"query":{"requestBody":{"$ref":"shared.json#/Body"}}}}}),
        ),
        (
            "shared.json",
            json!({"Body":{"content":{"application/json":{"schema":{"type":"string"}}}}}),
        ),
    ]);
    both(&dir, |contract| {
        located(
            contract,
            &id(
                &Uri::from_path(&dir.path().join("shared.json")).unwrap(),
                "/Body",
            ),
            "AMBIGUOUS_OPENAPI_CONTEXT",
        )
    });
}

#[test]
fn malformed_media_references_and_reference_cycles_are_located() {
    for (declaration, target, code, pointer) in [
        (
            json!({"$ref":null}),
            json!({}),
            "invalid-reference",
            "/paths/~1resource/query/responses/200/content/application~1json-seq",
        ),
        (
            json!({"$ref":7}),
            json!({}),
            "invalid-reference",
            "/paths/~1resource/query/responses/200/content/application~1json-seq",
        ),
        (
            json!({"$ref":"missing.json"}),
            json!({}),
            "invalid-reference",
            "/paths/~1resource/query/responses/200/content/application~1json-seq",
        ),
        (
            json!({"$ref":"#/components/mediaTypes/Bad"}),
            json!(false),
            "INVALID_HTTP_SHAPE",
            "/components/mediaTypes/Bad",
        ),
        (
            json!({"$ref":"#/components/mediaTypes/Bad"}),
            json!({"$ref":"#/components/mediaTypes/Bad"}),
            "HTTP_REFERENCE_CYCLE",
            "/components/mediaTypes/Bad/$ref",
        ),
    ] {
        let mut value = api(
            json!({"query":{"responses":{"200":{"content":{"application/json-seq":declaration}}}}}),
        );
        value["components"] = json!({"mediaTypes":{"Bad":target}});
        let dir = fixture(&[("api.json", value)]);
        both(&dir, |contract| {
            located(contract, &id(contract.entry(), pointer), code);
            let media = contract.operations().next().unwrap().responses()[0]
                .content()
                .remove(0);
            assert!(media.schema().is_none());
            assert!(media.item_schema().is_none());
            assert!(media.raw().get("$ref").is_some());
        });
    }
}

