#[test]
fn absent_yaml_item_schema_and_malformed_json_schema_slots_are_not_dropped() {
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("api.yaml"), "openapi: 3.2.0\ninfo: {title: Missing, version: '1'}\npaths:\n  /events:\n    query:\n      responses:\n        '200':\n          content:\n            application/json-seq:\n              itemSchema:\n").unwrap();
    let left = load(&dir, "api.yaml", ContractReader::Lossless);
    let right = load(&dir, "api.yaml", ContractReader::Fast);
    for contract in [&left, &right] {
        let source = id(
            contract.entry(),
            "/paths/~1events/query/responses/200/content/application~1json-seq/itemSchema",
        );
        located(contract, &source, "invalid-schema");
        let schema = contract.operations().next().unwrap().responses()[0].content()[0]
            .item_schema()
            .unwrap();
        assert_eq!(schema.id(), &source);
        assert_eq!(schema.raw(), &Value::Null);
        assert!(!schema.span().is_empty());
    }
    parity(&left, &right);
    for malformed in [Value::Null, json!(17), json!([]), json!("schema")] {
        let dir = fixture(&[(
            "api.json",
            api(
                json!({"query":{"responses":{"200":{"content":{"application/json-seq":{"itemSchema":malformed}}}}}}),
            ),
        )]);
        both(&dir, |contract| {
            located(
                contract,
                &id(
                    contract.entry(),
                    "/paths/~1resource/query/responses/200/content/application~1json-seq/itemSchema",
                ),
                "invalid-schema",
            )
        });
    }
}

#[test]
fn self_and_schema_id_are_scoped_without_rewriting_physical_identity() {
    for declaration in [
        json!("https://canonical.example.test/openapi.json"),
        Value::Null,
    ] {
        let mut value = api(
            json!({"query":{"requestBody":{"$ref":"must-not-load-under-retrieval-base.json"}}}),
        );
        value["$self"] = declaration.clone();
        let dir = fixture(&[("api.json", value)]);
        both(&dir, |contract| {
            let root = id(contract.entry(), "");
            if declaration.is_string() {
                assert_eq!(
                    contract.resource(&root).unwrap().canonical_uri(),
                    "https://canonical.example.test/openapi.json"
                );
                assert_eq!(contract.resource(&root).unwrap().source(), &root);
                assert!(
                    !contract
                        .diagnostics()
                        .iter()
                        .any(|d| d.source == root.child("$self"))
                );
            } else {
                located(contract, &root.child("$self"), "invalid-openapi-self");
                assert!(contract.resource_scope(&root).is_none());
            }
            located(
                contract,
                &id(contract.entry(), "/paths/~1resource/query/requestBody"),
                "invalid-reference",
            );
            assert!(
                contract
                    .operations()
                    .next()
                    .unwrap()
                    .request_body()
                    .unwrap()
                    .resolved_source()
                    .is_none()
            );
            assert_eq!(contract.documents().count(), 1);
        });
    }
    let dir = fixture(&[(
        "api.json",
        api(
            json!({"query":{"responses":{"200":{"content":{"application/json-seq":{"itemSchema":{
                "$id":"https://canonical.example.test/item", "$ref":"#Item", "$anchor":"Item"
            }}}}}}}),
        ),
    )]);
    both(&dir, |contract| {
        clean(contract);
        let source = id(
            contract.entry(),
            "/paths/~1resource/query/responses/200/content/application~1json-seq/itemSchema",
        );
        assert_eq!(
            contract.resource(&source).unwrap().canonical_uri(),
            "https://canonical.example.test/item"
        );
        assert_eq!(
            contract.schema(&source).unwrap().references()[0].target,
            Some(source.clone())
        );
        assert_eq!(contract.reachable_from(&[source]).len(), 1);
    });
    // The same words in a schema annotation or instance do not establish OAS
    // document identity, embedded resources, or schema anchor candidates.
    let mut value = api(
        json!({"query":{"responses":{"200":{"content":{"application/json-seq":{"itemSchema":{
            "$self":"https://annotation.example.test", "$anchor":"Item", "type":"object",
            "default":{"$id":"wrong.json","$self":"wrong.json","$anchor":"Item"},
            "properties":{"next":{"$ref":"#Item"}}
        }}}}}}}),
    );
    value["$id"] = json!("wrong-non-schema-root.json");
    let dir = fixture(&[("api.json", value)]);
    both(&dir, |contract| {
        clean(contract);
        assert_eq!(contract.documents().count(), 1);
        let source = id(
            contract.entry(),
            "/paths/~1resource/query/responses/200/content/application~1json-seq/itemSchema",
        );
        assert_eq!(
            contract
                .schema(&source.child("properties").child("next"))
                .unwrap()
                .references()[0]
                .target,
            Some(source)
        );
        assert!(
            contract
                .diagnostics()
                .iter()
                .any(|d| d.code == "unknown-schema-keyword")
        );
    });
}

#[test]
fn a_nested_schema_reference_retains_the_declared_media_schema_dialect_and_id_scope() {
    let dir = fixture(&[
        (
            "api.json",
            api(
                json!({"query":{"requestBody":{"content":{"application/json-seq":{
                    "itemSchema":{"$ref":"remote.json#/components/mediaTypes/Stream/itemSchema/$defs/Nested"}
                }}}}}),
            ),
        ),
        (
            "remote.json",
            json!({"openapi":"3.2.0","info":{"title":"Remote","version":"1"},"components":{"mediaTypes":{"Stream":{
                "itemSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"Nested":{"type":"string"}}}
            }}}}),
        ),
    ]);
    both(&dir, |contract| {
        clean(contract);
        let remote = Uri::from_path(&dir.path().join("remote.json")).unwrap();
        let nested = id(
            &remote,
            "/components/mediaTypes/Stream/itemSchema/$defs/Nested",
        );
        assert_eq!(
            contract.schema(&nested).unwrap().dialect(),
            &SchemaDialect::Uri("https://json-schema.org/draft/2020-12/schema".to_owned())
        );
        assert_eq!(contract.schemas().count(), 2);
        assert!(
            contract
                .schema(&id(&remote, "/components/mediaTypes/Stream/itemSchema"))
                .is_none()
        );
    });
    let dir = fixture(&[
        (
            "api.json",
            api(
                json!({"query":{"requestBody":{"content":{"application/json-seq":{
                    "itemSchema":{"$ref":"schema.json#/$defs/Resource/properties/nested"}
                }}}}}),
            ),
        ),
        (
            "schema.json",
            json!({"$defs":{"Resource":{"$id":"https://canonical.example.test/resource","properties":{"nested":{"type":"string"}}}}}),
        ),
    ]);
    both(&dir, |contract| {
        clean(contract);
        let external = Uri::from_path(&dir.path().join("schema.json")).unwrap();
        let declaration = id(&external, "/$defs/Resource");
        let resource = contract.resource(&declaration).unwrap();
        assert_eq!(
            resource.canonical_uri(),
            "https://canonical.example.test/resource"
        );
        assert_eq!(
            resource.declaration_source(),
            Some(&declaration.child("$id"))
        );
        assert!(
            !contract
                .source_span(resource.declaration_source().unwrap())
                .unwrap()
                .is_empty()
        );
        let source = id(
            contract.entry(),
            "/paths/~1resource/query/requestBody/content/application~1json-seq/itemSchema",
        );
        let target = declaration.child("properties").child("nested");
        assert_eq!(contract.reference_target(&source), Some(&target));
        assert_eq!(
            contract.resource_scope(&target).unwrap().resource(),
            &declaration
        );
        assert_eq!(
            contract.schema(&source).unwrap().references()[0].target,
            Some(target)
        );
    });
}

#[test]
fn duplicate_item_schema_anchors_and_duplicate_method_declarations_fail_explicitly() {
    let dir = fixture(&[(
        "api.json",
        json!({"openapi":"3.2.0","info":{"title":"Ambiguous","version":"1"},"components":{"mediaTypes":{
            "Use":{"itemSchema":{"$ref":"#Item"}},"First":{"itemSchema":{"$anchor":"Item","type":"string"}},"Second":{"itemSchema":{"$anchor":"Item","type":"integer"}}
        }}}),
    )]);
    both(&dir, |contract| {
        let source = id(contract.entry(), "/components/mediaTypes/Use/itemSchema");
        located(contract, &source, "invalid-reference");
        assert!(contract.reference_target(&source).is_none());
        assert!(
            contract.schema(&source).unwrap().references()[0]
                .target
                .is_none()
        );
    });
    let dir = tempfile::tempdir().unwrap();
    std::fs::write(dir.path().join("api.json"), r#"{"openapi":"3.2.0","info":{"title":"Duplicate","version":"1"},"paths":{"/resource":{"additionalOperations":{"COPY":{},"COPY":{}}}}}"#).unwrap();
    for reader in [ContractReader::Lossless, ContractReader::Fast] {
        let workspace = Arc::new(WorkspaceBuilder::new().root(dir.path()).build().unwrap());
        let error = Contract::from_workspace_with_reader(
            &workspace,
            &Uri::from_path(&dir.path().join("api.json")).unwrap(),
            reader,
        )
        .unwrap_err();
        assert!(
            error.to_string().contains("duplicate mapping key `COPY`"),
            "{error}"
        );
    }
}

#[test]
fn yaml_and_json_oas32_sources_keep_method_case_schema_identity_and_exact_values() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("api.yaml");
    std::fs::write(
        &path,
        r#"
openapi: 3.2.0
info: {title: Stream, version: '1'}
paths:
  /events:
    additionalOperations:
      "MiX\u0045d~":
        parameters:
          - name: whole
            in: querystring
            content:
              application/json:
                schema: {type: object}
        responses:
          '200':
            content:
              application/json-seq:
                itemSchema:
                  type: number
                  minimum: 1e-4000
                  maximum: 18446744073709551617
                  default: {schema: {$ref: never-load.json}, itemSchema: {$anchor: Fake}}
"#,
    )
    .unwrap();
    let yaml_left = load(&dir, "api.yaml", ContractReader::Lossless);
    let yaml_right = load(&dir, "api.yaml", ContractReader::Fast);
    parity(&yaml_left, &yaml_right);
    let expected = id(
        yaml_left.entry(),
        "/paths/~1events/additionalOperations/MiXEd~0/responses/200/content/application~1json-seq/itemSchema",
    );
    for contract in [&yaml_left, &yaml_right] {
        clean(contract);
        assert_eq!(
            contract.operations().next().unwrap().method().as_str(),
            "MiXEd~"
        );
        assert_eq!(contract.schemas().count(), 2);
        assert_eq!(
            contract.schema(&expected).unwrap().raw()["minimum"].to_string(),
            "1e-4000"
        );
        assert_eq!(
            contract.schema(&expected).unwrap().raw()["maximum"].to_string(),
            "18446744073709551617"
        );
    }
    std::fs::write(
        &path,
        serde_json::to_vec(yaml_left.document(yaml_left.entry()).unwrap()).unwrap(),
    )
    .unwrap();
    let json_left = load(&dir, "api.yaml", ContractReader::Lossless);
    let json_right = load(&dir, "api.yaml", ContractReader::Fast);
    parity(&json_left, &json_right);
    clean(&json_left);
    assert_eq!(yaml_left.schema_roots(), json_left.schema_roots());
    assert_eq!(
        yaml_left.schema(&expected).unwrap().raw(),
        json_left.schema(&expected).unwrap().raw()
    );
    assert_ne!(
        yaml_left.schema(&expected).unwrap().span(),
        json_left.schema(&expected).unwrap().span()
    );
}
